input.newString:
async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then(r => r.json()),
      fetch('/api/notifications').then(r => r.json()),
      fetch('/api/settings').then(r => r.json())
    ]);

    return { analytics, notifications, settings };
  } catch {
    return {
      analytics: { 
        totalUsers: 1000, 
        activeUsers: 250, 
        revenue: 50000,
        growth: 12.5
      },
      notifications: [
        { id: 1, message: 'System update completed', type: 'info' },
        { id: 2, message: 'New user registered', type: 'success' },
        { id: 3, message: 'Performance alert', type: 'warning' }
      ],
      settings: {
        theme: 'light',
        notificationsEnabled: true,
        autoRefresh: false,
        language: 'en'
      }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Analytics</h2>
      <div>
        <h3>Key Metrics</h3>
        <p>Total Users: {analytics.totalUsers}</p>
        <p>Active Users: {analytics.activeUsers}</p>
        <p>Revenue: ${analytics.revenue}</p>
        <p>Growth: {analytics.growth}%</p>
      </div>

      <div>
        <h3>Recent Notifications</h3>
        <ul>
          {notifications.map((notification: any) => (
            <li key={notification.id}>
              [{notification.type}] {notification.message}
            </li>
          ))}
        </ul>
      </div>

      <div>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Notifications: {settings.notificationsEnabled ? 'Enabled' : 'Disabled'}</p>
        <p>Auto Refresh: {settings.autoRefresh ? 'On' : 'Off'}</p>
        <p>Language: {settings.language}</p>
      </div>
    </div>
  );
}

